BiTree Create(elemtype x, BiTree lbt, BiTree rbt)   {BiTree  p;   if((p=(BiTNode*)malloc(sizeof(BiTNode)))==NULL)        return NULL;    p-&gt;data=x;    p-&gt;lchild=lbt;    p-&gt;rchild=rbt;     return p;  }

InsertL(bt, x, parent)
&nbsp;&nbsp;&nbsp; BiTree InsertL(BiTree bt，elemtype x，BiTree parent)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {BiTree&nbsp; p;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if (parent==NULL)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {printf("\n插入出错")；&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; return NULL;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if ((p=(BiTNode *)malloc(sizeof(BiTNode)))==NULL) return NULL;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; p-&gt;data=x;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; p-&gt;lchild=NULL;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; p-&gt;rchild=NULL;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if (parent-&gt;lchild==NULL) parent-&gt;lchild=p;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; else {p-&gt;lchild=parent-&gt;lchild;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; parent-&gt;lchild=p;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; return bt;&nbsp;&nbsp;&nbsp; }

