DeleteL(bt，parent)在二叉树bt中删除parent的左子树

 BiTree  DeleteL(BiTree bt，BiTree parent)      { BiTree  p;        if (parent==NULL||parent-&gt;lchild==NULL)          { printf("\n删除出错")；            return NULL;          }        p=parent-&gt;lchild;        parent-&gt;lchild=NULL;        free(p);   /*当*p为非叶子结点时，这样删除仅释放了所删子树根结点的空间，*//*若要删除子树分支中的结点，需用后面介绍的遍历操作来实现。*/        return bt;  }

