队列实现:遍历从根结点开始，首先将根结点入队，然后开始执行循环:结点出队、访问该结点、其左右儿子入队

非递归算法
其他函数构建二叉树的二叉链表在二叉树中查找结点值为x的结点void&nbsp; pre_find(BiTree bt, ElemType x, BiTree &amp;q)//用q返回{ //F是全局bool型变量，初值为FALSE&nbsp;&nbsp;&nbsp; if (bt &amp;&amp; F==FALSE)&nbsp;&nbsp;&nbsp;&nbsp; {&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if (bt-&gt;data==x)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {&nbsp;&nbsp; q=bt; F=TRUE;}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; else&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {&nbsp; pre_find(bt-&gt;lchild, x, q);&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; pre_find(bt-&gt;rchild, x, q)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }}

求二叉树中每个结点所处的层次void&nbsp; pre_level(BiTree p, int level){&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if (p)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; write(p-&gt;data, level);//实现时可用printf代替&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; pre_level(p-&gt;lchild; level+1);&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; pre_level(p-&gt;rchild; level+1);&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }}

求二叉树的高度void&nbsp; pre_height(BiTree p, int level){&nbsp;&nbsp;&nbsp;&nbsp; if (p)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {&nbsp; if (h&lt;level)&nbsp;&nbsp; h=level;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; pre_height(p-&gt;lchild, level+1);&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; pre_height(p-&gt;rchild,level+1);&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }}void&nbsp; post_height(BiTree bt,int &amp;h){&nbsp;&nbsp;&nbsp;&nbsp; if (bt==NULL) h=0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; else&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; { post_height(bt-&gt;lchild, h1);&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; post_height(bt-&gt;rchild,h2);&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; h:=1+max(h1,h2);&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }}

复制一颗二叉树void  pre_copy(BiTree bt; BiTree &amp;q){       if (bt)      {      new(q);             q-&gt;data= bt-&gt;data;             pre_copy(bt-&gt;lchild, q-&gt;lchild);             pre_copy(bt-&gt;rchild, q-&gt;rchild);      }     else             q=NULL;}

哈弗曼树
树的路径长度   从树根到每一个结点的路径上的分支数。
带权路径长度   结点的路径长度与该结点的权之积。
树的带权路径长度   树中所有叶子结点的带权路径长度之和。
最优二叉树(哈夫曼树)   带权路径长度WPL最小的二叉树。

哈夫曼树的应用最佳判定树哈夫曼编码
用于通信和数据传送中字符的二进制编码，可以使电文编码总长度最短左右分支分别为0,1字符在叶节点上


哈夫曼编码是不等长编码
哈夫曼编码是前缀编码，即任一字符的编码都不是另一字符编码的前缀
哈夫曼编码树中没有度为1的结点。若叶子结点的个数为n，则哈夫曼编码树的结点总数为 2n-1
发送过程：根据由哈夫曼树得到的编码表送出字符数据
接收过程：按左0、右1的规定，从根结点走到一个叶结点，完成一个字符的译码。反复此过程，直到接收数据结束

哈夫曼编码系统[问题描述]设计一个利用哈夫曼算法的编码系统，能完成以下基本要求。[基本要求]（1）键盘输入长为n的字符串， 统计其中每个字符的权值（出现频次），建立哈夫曼树；（2）编码：利用建好的哈夫曼树生成哈夫曼编码；（3）输出编码（在屏幕上显示）
#include &lt;stdio.h&gt;#include &lt;string.h&gt;#include &lt;stdlib.h&gt;typedef struct node{	char data;	struct node *parent,*left,*right;	int frequency;} Node,*huffman;//初始化树Node *create(char data, int frequency){	Node *new=(Node *)malloc(sizeof(Node));	new-&gt;data=data;	new-&gt;frequency=frequency;	new-&gt;left=NULL;	new-&gt;right=NULL;	new-&gt;parent=NULL;	return new;}//构建Huffman树huffman build(char data[],int freq[],int size){	Node *nodes=(Node *)malloc(sizeof(Node)*(size)*2);	int index[50];//使用索引数组进行排序	for(int i = 0; i &lt; 2 * size; i++)	{		nodes[i] = *create(data[i], freq[i]);		index[i] = i;	}	for(int k = 0; k &lt; size - 1; k++)//选择排序,按照频率大小排序	{		int min, temp;		for (int i = 2 * k; i &lt; size + k - 1; i++)		{			min = i;			for (int j = i + 1; j &lt; size + k; j++)			{				if (nodes[index[j]].frequency &lt; nodes[index[min]].frequency)				{					min = j;				}			}			temp = index[min];			index[min] = index[i];			index[i] = temp;		}		Node *n_parent = (Node *) malloc(sizeof(Node));  //创建父节点        n_parent-&gt;frequency = nodes[index[2 * k]].frequency + nodes[index[2 * k + 1]].frequency;          n_parent-&gt;left = &amp;nodes[index[2 * k]];        n_parent-&gt;right = &amp;nodes[index[2 * k + 1]];        nodes[index[2 * k]].parent = n_parent;        nodes[index[2 * k + 1]].parent = n_parent;        n_parent-&gt;data = '$';  // 父节点数据随意设置，这里使用'$'表示 		nodes[index[size + k]] = *n_parent;	}	return &amp;nodes[index[2 * size - 2]];}void find(huffman root, char code[], int top, char chara){	if (root-&gt;left != NULL)	{		code[top] = '0';		find(root-&gt;left, code, top + 1, chara);	}	if (root-&gt;right != NULL)	{		code[top] = '1';		find(root-&gt;right, code, top + 1, chara);	}	if (root-&gt;left == NULL &amp;&amp; root-&gt;right == NULL &amp;&amp; root-&gt;data == chara)	{//打印字符和对应Huffman编码		printf("%c: ", root-&gt;data);		for (int i = 0; i &lt; top; i++)		{			printf("%c", code[i]);		}		printf("\n");	}	return;}int main(){	char str[1005];	int freque[128]= {0};	memset(str, '\0', sizeof(str));	memset(freque, 0, sizeof(freque));	scanf("%s", str);//输入字符串	int len = strlen(str);//计算字符频率	for(int i = 0; i &lt; len; i++)	{		freque[(int)str[i]]++;	}	char data[200];	int freq[200], flag[200], size = 0;	memset(flag, 0, sizeof(flag));	//记录字符和对应频率	for(int i = 0; i &lt; len; i++)	{		if(flag[(int)str[i]] == 0)		{			flag[(int)str[i]] = 1;			freq[size] = freque[(int)str[i]];			data[size] = str[i];			size++;		}	}	huffman root = build(data, freq, size);	char code[100];  // 适当设置编码的最大长度	memset(code, '\0', sizeof(code));	//输出每个字符Huffman编码	for(int i = 0; i &lt; size; i++)	{		find(root, code, 0, data[i]);	}	return 0;}

树和森林树转换成二叉树树转换为二叉树的规则:每个结点左指针指向它的第一个孩子，右指针指向它在树中的相邻右兄弟，这个规则又称“左孩子右兄弟”。由于根结点没有兄弟，所以对应的二叉树没有右子树。


在兄弟结点之间加一连线;
对每个结点，只保留它与第一个孩子的连线，而与其他孩子的连线全部抹掉;
以树根为轴心，顺时针旋转45°。

森林转化为二叉树森林是由若干棵树组成的，所以完全可以理解为,森林中的每一棵树都是兄弟，可以按照兄弟的处理办法来操作。森林转换成二叉树的画法:

将森林中的每棵树转换成相应的二叉树;
每棵树的根也可视为兄弟关系，在每棵树的根之间加一根连线;
以第一棵树的根为轴心顺时针旋转45°。

树的遍历
先序遍历   先访问树的根结点，然后依次先根遍历根的每棵子树       ABEFCDG(二叉树先序)
后序遍历   先依次后根遍历根的每棵子树，然后访问树的根结点       EFBCGDA(二叉树中序)

森林的遍历先序遍历
访问第一棵树的根结点；先序遍历第一棵树的根的子树森林； 先序遍历除第一棵树外; 剩余的树构成的森林（逐棵先序遍历每棵子树&#x2F;  对应二叉树的先序遍历)  ##### 中序遍历中序遍历第一棵树的根的子树森林;访问第一棵树的根结点;中序遍历第一棵树外剩余的树构成的森林(逐棵后序遍历每棵子树&#x2F;对应二叉树的中序遍历)

Chapter6 图图的基本概念非线性结构，数据元素之间呈多对多的关系。

图的定义Graph&#x3D;(V,E)V：顶点(数据元素)的有穷非空集合。E：边的有穷集合。图的相关术语顶点 数据元素所构成的结点。无向图 边的顶点偶对是无序的。(vi, vj)和(vj, vi)代表同一条边(i $\ge$ j)。有向图 边的顶点偶对是有序的。有向边&lt; vi, vj &gt;也称为弧。vi是弧尾&#x2F;初始点； vj是弧头&#x2F;终端点。(无向)完全图 每个顶点与其余顶点都有边的无向图。顶点数为n时，边数e&#x3D;n(n-1)&#x2F;2有向完全图 每个顶点与其余顶点都有弧的有向图。顶点数为n时，弧数e&#x3D;n(n-1)思考：一无向图的顶点个数为n，则该图最多有（  n(n-1)&#x2F;2  ）条边。稀疏图 有很少边或弧的图。稠密图 有较多边或弧的图。权 图中的边或弧具有一定的大小的概念。网 边&#x2F;弧带权的图。邻接 有边&#x2F;弧相连的两个顶点之间的关系。存在(vi, vj)，则称vi和vj互为邻接点；存在&lt;vi, vj&gt;，则称vi邻接到vj， vj邻接于vi关联(依附) 边&#x2F;弧与顶点之间的关系。存在(vi, vj)&#x2F; &lt;vi, vj&gt;， 则称该边&#x2F;弧关联于vi和vj子图 对于图G&#x3D;(V,E)和G’&#x3D;(V’,E’)，如果V’V，E’ E，且E’关联的顶点都在V’中，则称G’是G的子图。生成子图 由图的全部顶点和部分边组成的子图称为原图的生成子图。顶点的度   与该顶点相关联的边的数目，记为D(v)。入度ID(v)：有向图中，以该顶点为弧头的弧数目。出度OD(v)：有向图中，以该顶点为弧尾的弧数目。顶点数n、边数e和度数之间的关系:$e&#x3D;\frac{1}{2} \sum_{i&#x3D;1}^{n} D\left ( vi \right )$思考：在一个无向图中，所有顶点的度数之和等于所有边数2倍，在一个有向图中，所有顶点的入度之和等于所有顶点出度之和的1倍。在有n个顶点的有向图中，每个顶点的度最大可达2(n-1)。路径   接续的边构成的顶点序列。路径长度   路径上边或弧的数目&#x2F;权值之和。回路(环)   第一个顶点和最后一个顶点相同的路径。简单路径   除路径起点和终点可以相同外，其余顶点均不相同的路径。简单回路(简单环)   除路径起点和终点相同外，其余项点均不相同的路径。n个顶点的无向完全图中,两个顶点之间简单路径数目为多少？1 + A(n-2,1) + A(n-2,2) + … + A(n-2,n-2)其中A(m,n)是m取n的排列数。连通图   无向图中，任何一对顶点间都存在路径。连通分量   无向图中的极大连通子图。思考：n个顶点组成的连通无向图，其边的个数至少为n-1。思考：一个有n个结点的无向图，最少有（ 1 ）个连通分量，最多有（n）个连通分量。若G是一个非连通无向图，共有28条边，则该图至少有_9_个顶点。生成树   包含图中全部顶点的极小连通子图有向树   图中恰有一个顶点入度为0，其余顶点入度均为1。生成森林   有向图中，包含所有顶点的若干棵有向树构成的子图。
图的存储结构数组+邻接矩阵&#x2F;加权邻接矩阵(顺序存储方式)无权值的有向图的邻接矩阵 设有向图具有 n 个顶点，则用 n 行 n 列的布尔矩阵 A 表示该有向图;并且 A[i,j]  &#x3D;  1 , 如果i 至 j 有一条有向边；A[i,j] &#x3D; 0如果 i 至 j 没有一条有向边。 注意： 顶点i出度: i行之和。顶点i入度: i列之和。
无权值的无向图的邻接矩阵设无向图具有 n 个顶点，则用 n 行 n 列的布尔矩阵 A 表示该无向图；并且 A[i,j]  &#x3D;  1 , 如果i 至 j 有一条无向边；A[I,j] &#x3D; 0如果 i 至 j 没有一条无向边。i结点的度: i行或i列之和。必然为对称矩阵，可压缩为上三角矩阵或下三角矩阵。思考：n个顶点的连通图用邻接矩阵表示时,该矩阵至少有2(n-1)个非零元素。n个顶点的强连通图用邻接矩阵表示时,该矩阵至少有n个非零元素
有向图的加权邻接矩阵设有向图具有 n 个顶点，则用 n 行 n 列的矩阵 A 表示该有向图;并且 A[i,j]  &#x3D;  a , 如果i 至 j 有一条有向边且它的权值为a。A[i,j] &#x3D; ∞,0 或其它标志；如果 i 至 j 没有一条有向边。优点：判断任意两点之间是否有边方便，仅耗费 O(1) 时间。缺点：即使 &lt;&lt; $n^{2}$ 条边，也需内存 $n^{2}$ &#x2F;2 单元，太多; 仅读入数据耗费  O( $n^{2}$ )  时间，太长。
邻接表顺序存储+链式存储

设有向图或无向图具有 n 个顶点，则用 顶点表、边表表示该有向图或无向图。顶点表：用数组的形式存放所有的顶点。边表（出边表）：从某个顶点出发的边组成的单链表。优点：内存消耗 ＝  顶点数 ＋ 边数。缺点：确定 i –&gt; j 是否有边，最坏需耗费 O(n) 时间。无向图同一条边表示两次边表空间浪费一倍。有向图中寻找进入某结点的边，非常困难。顶点表中的结点的表示： 用数组
datafirstarcdata:顶点的数据域，保存顶点的数据元素的值。firstarc:顶点的指针域，指向自该顶点出发的的第一条边的边表结点地址。（出）边表中的结点的表示：

infoadjvexnextarcinfo:边结点的数据场，保存边的权值等。adjvex:边结点的指针，给出本条边依附的另一顶点（非出发顶点）的地址。nextarc:顶点的指针，给出自该顶点出发的的下一条边的 边结点的地址。邻接矩阵适合稠密图 邻接表适合稀疏图

图的遍历两种遍历方式深度优先遍历 (树的先根遍历的推广)广度优先遍历 (树的按层次遍历的推广)
深度优先遍历注意：每个顶点只能被访问一次，因为一个顶点可以和其它的任何顶点相邻接，为了避免对一个顶点的重复访问，必须对访问过的顶点加以标记。顶点的邻接顶点的次序是任意的，因此深度优先搜索的序列可能有多种。遍历过程

选中第一个被访问的顶点。

对顶点作已访问过的标志。

依次从顶点的未被访问过、 邻接顶点出发，进行深度优先遍历,转向2。

如果还有顶点未被访问，则选中一个起始顶点，转向2。

所有的顶点都被访问到，则结束。
bool visited[MAX_VERTEX_NUM];	//访问标记数组/*从顶点出发，深度优先遍历图G*/void DFS(Graph G, int v){	int w;	visit(v);	//访问顶点	visited[v] = TRUE;	//设已访问标记	//FirstNeighbor(G,v):求图G中顶点v的第一个邻接点，若有则返回顶点号，否则返回-1。	//NextNeighbor(G,v,w):假设图G中顶点w是顶点v的一个邻接点，返回除w外顶点v	for(w = FirstNeighbor(G, v); w&gt;=0; w=NextNeighor(G, v, w)){		if(!visited[w]){	//w为u的尚未访问的邻接顶点			DFS(G, w);		}	}}/*对图进行深度优先遍历*/void DFSTraverse(MGraph G){	int v; 	for(v=0; v&lt;G.vexnum; ++v){		visited[v] = FALSE;	//初始化已访问标记数据	}	for(v=0; v&lt;G.vexnum; ++v){	//从v=0开始遍历		if(!visited[v]){			DFS(G, v);		}	}}

算法时间复杂度分析    主要操作：查找每个顶点的所有邻接点

邻接矩阵   O(n2)

邻接表   无向图  O(n+2e)有向图  O(n+e)

思考：如果对于图而言，深度优先遍历可以判断其是否有环吗？可以。 dfs（v）结束前出现顶点u到v的回边，则图中必有包含顶点v和u的回路



非递归的算法思想(1)访问一个顶点，并记录它已被访问；将它的所有未访问的邻接顶点入栈；(2)如果栈空，则退出；否则，栈中一顶点出栈；(3)如果该顶点已被访问过，则转(2)否则，转(1)非递归的算法实现]void Traver(AdjList g,vertype v)&#x2F;&#x2F;图g以邻接表为存储结构，算法从顶点v开始实现非递归深度优先遍历。
{struct arc *stack[];   visited[v]=1；printf(v);  //输出顶点v   top=0; p=g[v].firstarc; stack[++top]=p;   while(top&gt;0 || p!=NULL)     {        while (p)              if (p &amp;&amp; visited[p-&gt;adjvex]) p=p-&gt;next;            else {printf(p-&gt;adjvex); visited[p-&gt;adjvex]=1;                  stack[++top]=p; p=g[p-&gt;adjvex].firstarc;}//else        if (top&gt;0) {p=stack[top--]; p=p-&gt;next; }     }//while  }//算法结束。

算法讨论： 以上算法适合连通图，若是非连通图，则再增加一个主调算法,其核心语句是
for (vi=1;vi&lt;=n;vi++) if (!visited[vi]) Traver(g,vi);

广度优先遍历遍历过程1、选中第一个被访问的结点 V2、对结点 V 作已访问过的标志。3、依次从结点 V 的未被访问过的第一个、第二个、第三个……第 M个邻接结点 W1 、W2、W3…… Wm ，且进行标记。4、依次访问结点 W1 、W2、W3…… Wm的邻接结点，且进行标记。5、如果还有结点未被访问，则选中一个起始结点，也标记为V，转向2。6、所有的结点都被访问到，则结束。
算法思想
访问顶点v，并记录它已被访问； 顶点v入队列；

如果队列空，则退出；否则，从队中取出一顶点；

求该顶点的一个邻接点；如果此邻接点未被访问，则访问它，并记录它已被访问，将其入队列；

如果该顶点还有下一个邻接点，则转(3);否则，转(2)
void BFSTraverse(MGraph G){	int i, j;	Queue Q;	for(i = 0; i&lt;G,numVertexes; i++){		visited[i] = FALSE;	}	InitQueue(&amp;Q);	//初始化一辅助用的队列	for(i=0; i&lt;G.numVertexes; i++){		//若是未访问过就处理		if(!visited[i]){			vivited[i] = TRUE;	//设置当前访问过			visit(i);	//访问顶点			EnQueue(&amp;Q, i);	//将此顶点入队列			//若当前队列不为空			while(!QueueEmpty(Q)){				DeQueue(&amp;Q, &amp;i);	//顶点i出队列				//FirstNeighbor(G,v):求图G中顶点v的第一个邻接点，若有则返回顶点号，否则返回-1。				//NextNeighbor(G,v,w):假设图G中顶点w是顶点v的一个邻接点，返回除w外顶点v				for(j=FirstNeighbor(G, i); j&gt;=0; j=NextNeighbor(G, i, j)){					//检验i的所有邻接点					if(!visited[j]){						visit(j);	//访问顶点j						visited[j] = TRUE;	//访问标记						EnQueue(Q, j);	//顶点j入队列					}				}			}		}	}}

算法时间复杂度分析主要操作：查找每个顶点的所有邻接点邻接矩阵 O($n^{2}$ )邻接表 无向图 O(n+2e) 有向图 O(n+e)

已知一无向图G&#x3D;（V，E），其中V&#x3D;{a,b,c,d,e } E&#x3D;{(a,b),(a,d),(a,c),(d,c),(b,e)}现用某一种图遍历方法从顶点a开始遍历图，得到的序列为abecd，则采用的是______遍历方法。


假设以邻接矩阵作为图的存储结构，编写算法判别在给定的有向图中是否存在一个简单有向回路，若存在，则以顶点序列的方式输出该回路（找到一条即可）。（注：图中不存在顶点到自己的弧）

void find_cycle() //判断是否有回路，有则输出邻接矩阵。visited数组为全局变量。     {for (i=1;i&lt;=n;i++) visited[i]=0;      for (i=1;i&lt;=n;i++ ) if (!visited[i])  dfs(i);}//find_cyclevoid dfs(int v){   visited[v]=1;    for(j=1;j&lt;=n;j++ )          if (g[v][j]!=0) //存在边(v,j)              if (visited[j]!=1) {if (!visited[j]) dfs(j); }              else {cycle=1; Print(j,j);}    visited[v]=2;}void  Print(int v,int start )  //输出从顶点start开始的回路。{for(i=1;i&lt;=n;i++)    if(g[v][i]!=0 &amp;&amp; visited[i]==1 )  //若存在边（v,i），且顶点i的状态为1。      {printf(“%d”,v); if(i==start) printf(“\n”); else Print(i,start);break;}//if    }//Print

有向图判断回路要比无向图复杂。利用深度优先遍历，将顶点分成三类：未访问；已访问但其邻接点未访问完;已访问且其邻接点已访问完。用0，1，2表示这三种状态。若dfs（v）结束前出现顶点u到v的回边，则图中必有包含顶点v和u的回路。对应程序中v的状态为1，而u是正访问的顶点，若我们找出u的下一邻接点的状态为1，就可以输出回路了。

图的连通性无向图的连通分量和生成树连通图的生成树
生成树是图G的一个子图，该子图是包含G的所有顶点的树(或者是自由树—未确定根结点)。
若图G有n个顶点，则其生成树必具有n-1条边。
生成树是包含图中所有顶点的极小连通子图。
生成树可以通过对图的深度&#x2F;广度优先遍历而得到，称之为深度&#x2F;广度优先生成树。在算法中，访问一个结点时vj，同时记录它的父结点vi，(vi ,vj)是生成树的一条边。一般情况，BFS(广度优先搜索)生成树的树高小于DFS(深度优先搜索)生成树的高度。一个图的生成树是不唯一的


从不同的顶点出发
采用不同的存储结构和存储顺序

最小生成树由一个网络（带权图）生成的各边的权数总和最小的生成树称为最小生成树，记为MST。

MST性质：设N&#x3D;(V,{E})是一个连通的带权图，U是V的真子集，若边(u,v)[u ${\in }$ U,v${\in }$V-U]是E中所有一个端点在U内，一个端点不在U内的边中权值最小的一条边(轻边)，则一定存在G的一棵生成树包括此边。

证明：假定存在一棵不包括边  ( u, v ) 在内的最小代价生成树，设其为 T。将边( u, v )添加到树 T ，则形成一条包含  ( u, v ) 的回路。因此，必定存在另一条边  ( u‘ ，v‘  ) ，且 u’ 属于 U , v ‘   属于 V - U。删去边 ( u‘   ，v‘  ) ，得到另一棵生成树 T ‘  ; 因为边 ( u, v ) 的代价小于边  ( u‘   ，v‘  ) 的代价，所以新的生成树T ‘将是代价最小的树。和原假设矛盾。   注：新的生成树T‘是树的理由：连通且无回路。

普里姆（Prim）算法Prim算法构造最小生成树的过程如下图所示。初始时从图中任取一顶点(如顶点加入树T，此时树中只含有一个顶点，之后选择一个与当前T中顶点集合距离最近的顶点，并将该顶点和相应的边加入T，每次操作后T中的顶点数和边数都增1。以此类推，直至图中所有的顶点都并入T，得到的T就是最小生成树。此时T中必然有n-1条边。通俗点说就是：从一个顶点出发，在保证不形成回路的前提下，每找到并添加一条最短的边，就把当前形成的连通分量当做一个整体或者一个点看待，然后重复“找最短的边并添加”的操作。
算法步骤1)初始化closedge[v](v&#x3D;1..n) O(n)2)重复n-1次以下操作：2.1)在closedge[v](v&#x3D;1..n)中选择最小且非0的 lowcost，记录其v值(设为k)和相应的vex； O( ${n}^{2}$ )2.2)输出该边(vex,k)； O(n)2.3)顶点k并入U集：closedge[k].lowcost&#x3D;0； O(n)2.4)调整候选边集closedge[v](v&#x3D;1..n)： O( ${n}^{2}$ )若gn[k,v] &lt; closedge[v].lowcost，则更改closedge[v]：vex&#x3D;k, lowcost&#x3D;gn[k,v] O( ${n}^{2}$ )算法特点 适用于稠密图
/*Prim算法生成最小生成树*/void MiniSpanTree_Prim(G){	int min, i, j, k;	int adjvex[MAXVEX];	//保存相关顶点下标	int lowcost[MAXVEX];	//保存相关顶点间边的权值	lowcost[0] = 0;	//初始化第一个权值为0，即v0加入生成树	//lowcost的值为0，在这里就是此下标的顶点已经加入生成树	adjvex[0] = 0;	//初始化第一个顶点下标为0	for(i=1; i&lt;G.numVertexes; i++){		lowcost[i] = G.arc[0][i];	//将v0顶点与之组成边的权值存入数组		adjvex[i] = 0;	//初始化都为v0的下标	}	for(i=1; i&lt;G.numVertexes; i++){		min = INFINITY;	//初始化最下权值为∞，通常设置一个不可能的很大的数字		j = 1; k = 0;		//循环全部顶点		while(j &lt; G.numVertexes){			//如果权值不为0且权值小于min			if(lowcost[j] != 0 &amp;&amp; lowcost[j] &lt; min){				min = lowcost[j];	//则让当前权值成为最小值				k = j;	//将当前最小值的下标存入k			}			j++;		}		print("(%d, %d)", adjvex[k], k);	//打印当前顶点边中权值的最小边		for(j=1; j&lt;G.numvertexes; j++){			//若下标为k顶点各边权值小于此前这些顶点未被加入生成树权值			if(lowcost[j] != 0 &amp;&amp; G.arc[k][j] &lt; lowcost[j]){				lowcost[j] = G.arc[k][j];	//将较小权值存入lowcost				adjvex[j] = k;	//将下标为k的顶点存入adjvex			}		}	}}

克鲁斯卡尔（Kruskal）算法与Prim算法从顶点开始扩展最小生成树不同，Kruskal 算法是一种按权值的递增次序选择合适的边来构造最小生成树的方法。
Kruskal算法构造最小生成树的过程如下图所示。初始时为只有n个顶点而无边的非连通图T &#x3D; V , T&#x3D; {V, {}}T&#x3D;V,，每个顶点自成一个连通分量，然后按照边的权值由小到大的顺序，不断选取当前未被选取过且权值最小的边，若该边依附的顶点落在T中不同的连通分量上，则将此边加入T TT，否则舍弃此边而选择下一条权值最小的边。以此类推，直至T TT中所有顶点都在一个连通分量上。
算法步骤
1)初始化T：顶点集&#x3D;所有顶点，每个独立的顶点作为一棵树，边集&#x3D;ø； O(n)

依权值递增序对图G的边排序，结果为E[1..e] O(elge)

依次检测E中的各边(u,v)： O(elge)3.1) 若u和v分属于T中两棵不同的树，则将该边加入T，并合并u和v分属的两棵树3.2) 若T中所有顶点尚未属于一棵树，转3)算法特点   适用于稀疏图
/*对边集数组Edge结构的定义*/typedef struct{	int begin;	int end;	int weight;}Edge;

于是Kruskal算法代码如下，左侧数字为行号。其中MAXEDGE为边数量的极大值，此处大于等于15即可，MAXVEX为顶点个数最大值，此处大于等于9即可。
/*Kruskar算法生成最小生成树*/void MiniSpanTree_Kruskal(MGraph G){	int i, n, m;	Edge edges[MAXEDGE];	//定义边集数组	int parent[MAXVEX];	//定义一数组用来判断边与边是否形成环路	/*此处省略将邻接矩阵G转化为边集数组edges并按照权由小到大排序的代码*/	for(i=0; i&lt;G.numVertexes; i++){		parent[i] = 0;	//初始化数组为0	}	for(i=0; i&lt;G.numVertexes; i++){		n = Find(parent, edges[i].begin);		m = Find(parent, edge[i],end);		/*假如n与m不等，说明此边没有与现有生成树形成环路*/		if(n != m){		/*将此边的结尾顶点放入下标为起点的parent中		表示此顶点已经在生成树集合中*/		parent[n] = m;		printf("(%d, %d, %d)", edges[i].begin, 						edges[i].end, edges[i].weight);		}	}}/*查找连线顶点的尾部下标*/int Find(int *parent, int f){	while(parent[f] &gt; 0){		f = parent[f];	}	return f;}

Dijkstra算法Dijkstra算法用于构建单源点的最短路径—，即图中某个点到任何其他点的距离都是最短的。例如，构建地图应用时查找自己的坐标离某个地标的最短距离。可以用于有向图，但是不能存在负权值。我们以上图为例，通俗点说，这个迪杰斯特拉(Dijkstra) 算法，它并不是一下子求出了$v_{0}$到$v_{8}$ 的最短路径，而是一步步求出它们之间顶点的最短路径，过程中都是基于已经求出的最短路径的基础上，求得更远顶点的最短路径，最终得到你要的结果。Dijkstra算法设置一个集合S记录已求得的最短路径的顶点。在构造的过程中还设置了个辅助数组:dist[]：记录从源点$v_{0}$到其他各顶点当前的最短路径长度，它的初态为：若从$v_{0}$ ​到$v_{i}$​;有弧，则dist[i]为弧上的权值；否则置dist[i]为∞ 。
Floyd 算法基本思想：弗洛伊德算法定义了两个二维矩阵：
矩阵D记录顶点间的最小路径例如D[0][3]&#x3D; 10，说明顶点0 到 3 的最短路径为10；矩阵P记录顶点间最小路径中的中转点例如P[0][3]&#x3D; 1 说明，0 到 3的最短路径轨迹为：0 -&gt; 1 -&gt; 3。它通过3重循环，k为中转点，v为起点，w为终点，循环比较D[v][w] 和 D[v][k] + D[k][w] 最小值，如果D[v][k] + D[k][w] 为更小值，则把D[v][k] + D[k][w] 覆盖保存在D[v][w]中。
#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#define MAXN 10 #define INF = 1000typedef struct struct_graph{    char vexs[MAXN];    int vexnum;//顶点数     int edgnum;//边数     int matirx[MAXN][MAXN];//邻接矩阵 } Graph;int pathmatirx[MAXN][MAXN];//记录对应点的最小路径的前驱点，例如p(1,3) = 2 说明顶点1到顶点3的最小路径要经过2 int shortPath[MAXN][MAXN];//记录顶点间的最小路径值void short_path_floyd(Graph G, int P[MAXN][MAXN], int D[MAXN][MAXN]){    int v, w, k;    //初始化floyd算法的两个矩阵     for(v = 0; v &lt; G.vexnum; v++){        for(w = 0; w &lt; G.vexnum; w++){            D[v][w] = G.matirx[v][w];            P[v][w] = w;        }    }    //这里是弗洛伊德算法的核心部分     //k为中间点     for(k = 0; k &lt; G.vexnum; k++){        //v为起点         for(v = 0 ; v &lt; G.vexnum; v++){            //w为终点             for(w =0; w &lt; G.vexnum; w++){                if(D[v][w] &gt; (D[v][k] + D[k][w])){                    D[v][w] = D[v][k] + D[k][w];//更新最小路径                     P[v][w] = P[v][k];//更新最小路径中间顶点                 }            }        }    }    printf("\n初始化的D矩阵\n");    for(v = 0; v &lt; G.vexnum; v++){        for(w = 0; w &lt; G.vexnum; w++){            printf("%d ", D[v][w]);        }        printf("\n");    }    printf("\n初始化的P矩阵\n");    for(v = 0; v &lt; G.vexnum; v++){        for(w = 0; w &lt; G.vexnum; w++){            printf("%d", P[v][w]);        }        printf("\n");    }    v = 0;    w = 3;    //求 0 到 3的最小路径    printf("\n%d -&gt; %d 的最小路径为：%d\n", v, w, D[v][w]);    k = P[v][w];    printf("path: %d", v);//打印起点    while(k != w){        printf("-&gt; %d", k);//打印中间点        k = P[k][w];     }    printf("-&gt; %d\n", w);}int main(){    int v, w;    Graph G;    printf("请输入顶点数:\n");    scanf("%d", &amp;G.vexnum);    printf("请输入初始矩阵值：\n");    for(v = 0; v &lt; G.vexnum; v++){        for(w = 0; w &lt; G.vexnum; w++){            scanf("%d", &amp;G.matirx[v][w]);        }    }    printf("\n输入的矩阵值：\n");    for(v = 0; v &lt; G.vexnum; v++){        for(w = 0; w &lt; G.vexnum; w++){            printf("%d ", G.matirx[v][w]);        }        printf("\n");    }    short_path_floyd(G, pathmatirx, shortPath);}


拓扑排序二、算法对一个AOV网进行拓扑排序的算法有很多，下面介绍比较常用的一种方法的步骤:

从AOV网中选择一个没有前驱的顶点并输出。

从网中删除该顶点和所有以它为起点的有向边。

重复1和2直到当前的AOV网为空或当前网中不存在无前驱的顶点为止。如果输出顶点数少了，哪怕是少了一个，也说明这个网存在环(回路)，不是AOV网。
bool TopologicalSort(Graph G){	InitStack(S);	//初始化栈，存储入度为0的顶点	for(int i=0; i&lt;G.vexnum; i++){		if(indegree[i] == 0){			Push(S, i);	//将所有入度为0的顶点进栈		}	}	int count = 0;	//计数，记录当前已经输出的顶点数	while(!IsEmpty(S)){	//栈不空，则存在入度为0的顶点		Pop(S, i);	//顶点元素出栈		printf("%d ", i);	//输出顶点i		count++;		for(p=G.vertices[i].finstarc; p; p=p-&gt;nextarc){			//将所有i指向的顶点的入度减1，并且将入度减为0的顶点压入栈S			v = p-&gt;adjvex;			if(!--indegree[v]){				Push(S, v);	//入度为0，则入栈			}		}	}	if(count &lt; G.vexnum){		return false;	//输出顶点少了，有向图中有回路，排序失败	}else{		return true;	//拓扑排序成功	}}

由于输出每个顶点的同时还要删除以它为起点的边，故拓扑排序的时间复杂度为O ( V + E ) O(V+E)O(V+E)。此外，利用深度优先遍历也可实现拓扑排序。


用拓扑排序算法处理AOV网时，应注意以下问题:

入度为零的顶点，即没有前驱活动的或前驱活动都已经完成的顶点，工程可以从这个顶点所代表的活动开始或继续。
若一个顶点有多个直接后继，则拓扑排序的结果通常不唯一；但若各个顶点已经排在一个线性有序的序列中，每个顶点有唯一的前驱后继关系，则拓扑排序的结果是唯一的。
由于AOV网中各顶点的地位平等，每个顶点编号是人为的，因此可以按拓扑排序的结果重新编号，生成AOV网的新的邻接存储矩阵，这种邻接矩阵可以是三角矩阵；但对于一般的图来说，若其邻接矩阵是三角矩阵，则存在拓扑序列；反之则不一定成立。
